// spec: specs/home.md
// seed: tests/seed.client.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/client.json') });

test.describe('מסך הבית — "הצג/י הכל" ליד "פעולות אחרונות"', () => {
  test('"הצג/י הכל" ליד "פעולות אחרונות" פותח את "פעולות אחרונות" המלא, "חזרה" — לארנק @mobile @prod-safe (#85e61705)', async ({ page }) => {
    // 1. /wallet, לחכות לבלוק "פעולות אחרונות"
    await page.goto('/wallet');
    const recent = page.getByTestId('section-recent');
    await expect(recent).toBeVisible();

    // 2. "הצג/י הכל" בבלוק הזה
    await recent.getByTestId('section-recent-action').click();

    // 3. לחכות להיעלמות "טוען…" ולרשימה
    await expect(page).toHaveURL(/\/wallet\/recent$/);
    await expect(page.getByTestId('recent-loading')).toHaveCount(0);
    const list = page.getByTestId('recent-actions-list');
    await expect(list).toBeVisible();
    await expect(page.getByText('פעולות אחרונות', { exact: true }).first()).toBeVisible();

    const rows = page.getByTestId(/^recent-[0-9a-f-]{36}$/);
    expect(await rows.count()).toBeGreaterThanOrEqual(1);
    await expect(rows.first()).toContainText(/(היום|\d{1,2} ב\S+) \d{1,2}:\d{2}/);
    await expect(rows.first()).toContainText(/[+-]₪[\d,.]+/);

    const topUps = rows.filter({ hasText: 'טעינת כסף' });
    const withdrawals = rows.filter({ hasText: 'משיכת כסף' });
    expect(await topUps.count()).toBeGreaterThanOrEqual(1);
    expect(await withdrawals.count()).toBeGreaterThanOrEqual(1);
    for (const group of [topUps, withdrawals]) {
      const n = await group.count();
      for (let i = 0; i < n; i++) await expect(group.nth(i)).toContainText('הושלם');
    }

    // 4. "חזרה"
    await page.getByTestId('back-button').click();
    await expect(page).toHaveURL(/\/wallet$/);
    await expect(page.getByTestId('section-recent')).toBeVisible();
  });
});
